      case 'subagent_send':
        return text(await post('/api/subagents/send', { ...input, taskId: task, parentRunId }))
      case 'subagent_read':
      case 'subagent_wait':
      case 'subagent_cancel':
        return text(
          await post(`/api/subagents/${name.slice('subagent_'.length)}`, {
            id: string(input.id, 'id'),
            timeoutMs: input.timeoutMs,
            taskId: task,
            parentRunId,
