      case 'artifact_list':
        artifacts()
        return text(await post('/api/artifacts/list', { taskId: task }))
      case 'artifact_read':
        artifacts()
        return text(
          await post('/api/artifacts/read', {
            taskId: task,
            id: input.id,
            revision: input.revision,
          }),
