      case 'artifact_create':
      case 'artifact_update':
        artifacts()
        writable()
        return text(
          await post(
            name === 'artifact_create' ? '/api/artifacts/create' : '/api/artifacts/update',
            { ...input, taskId: task, parentRunId },
          ),
